         {
             encrlen  = tvb_get_ntohs(tvb, offset);
             skip = 2;
@@ -4271,7 +4271,7 @@ ssl_generate_keyring_material(SslDecryptSession*ssl_session)
             case TLSV1DOT1_VERSION:
             case DTLSV1DOT0_VERSION:
             case DTLSV1DOT0_OPENSSL_VERSION:
